#!/usr/bin/env python3
import sys
import subprocess
import importlib
from pathlib import Path

# --- pytest auto-install ---
try:
    import pytest
except ImportError:
    print("pytest not found, installing...")
    subprocess.check_call([sys.executable, "-m", "pip", "install", "pytest"])
    pytest = importlib.import_module("pytest")

# --- directory config ---
TASK_DIR = Path(__file__).resolve().parent
PROJECT_ROOT = TASK_DIR.parent
WORKSPACE_DIR = Path(__file__).parent / "workspace"


def _search_bases():
    # Where to look for agent output files.
    return [
        Path(__file__).parent / "workspace",
        Path(__file__).parent,
        WORKSPACE_DIR,
        TASK_DIR,
    ]


def _find_snapshot():
    # Where to look for snapshots.json.
    for path in (
        Path.home() / "snapshots.json",
        Path(__file__).parent / "snapshots.json",
        Path(__file__).parent / "workspace" / "snapshots.json",
        TASK_DIR / "snapshots.json",
        TASK_DIR / "snapshot.json",
    ):
        if path.is_file():
            return path
    return None


def _find_memory_md():
    # Find memory.md (case-insensitive stem).
    for base in _search_bases():
        if not base.exists():
            continue
        for path in base.rglob("*.md"):
            try:
                if path.is_file() and path.stem.lower() == "memory":
                    return path.resolve()
            except OSError:
                continue
    return None

# --- tests go here ---

import json
import os
import re


DELIVERABLES = ("budget_calculations.md", "inventory_review.md", "fundraising_plan.md")


def _has_deliverables(root):
    return root.is_dir() and all((root / name).is_file() for name in DELIVERABLES)


def _candidate_output_roots(base):
    """Return output directories under base, including canonical nested agent workspaces."""
    candidates = [
        base,
        base / "openclaw-workspace",
        base / "workspace",
        base / "workspace" / "openclaw-workspace",
    ]

    if base.exists():
        try:
            candidates.extend(path for path in base.rglob("openclaw-workspace") if path.is_dir())
        except OSError:
            pass

    found = []
    seen = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            continue
        if resolved in seen or not _has_deliverables(resolved):
            continue
        seen.add(resolved)
        found.append(resolved)
    return found


def _select_output_root(base):
    candidates = _candidate_output_roots(base)
    if len(candidates) == 1:
        return candidates[0]
    if candidates:
        canonical = [path for path in candidates if path.name == "openclaw-workspace"]
        if len(canonical) == 1:
            return canonical[0]
        names = ", ".join(str(path) for path in sorted(candidates))
        pytest.fail(
            "Multiple possible output directories found "
            f"({names}). Set VERIFIER_TARGET to the exact run directory being evaluated."
        )
    return None


def _target_root():
    """Return the candidate output directory without accidentally mixing sample runs."""
    env_target = os.environ.get("VERIFIER_TARGET") or os.environ.get("AGENT_WORKSPACE")
    if env_target:
        root = Path(env_target).expanduser()
        if not root.is_absolute():
            root = TASK_DIR / root
        assert root.is_dir(), f"Verifier target directory does not exist: {root}"
        selected = _select_output_root(root)
        assert selected is not None, (
            "No deliverable directory found at target or under canonical "
            f"openclaw-workspace paths: {root}"
        )
        return selected

    for root in (WORKSPACE_DIR, TASK_DIR / "workspace", Path.cwd(), TASK_DIR):
        selected = _select_output_root(root)
        if selected is not None:
            return selected

    candidate_roots = []
    for child in TASK_DIR.iterdir():
        if not child.is_dir():
            continue
        candidate_roots.extend(_candidate_output_roots(child))

    if len(candidate_roots) == 1:
        return candidate_roots[0]

    if candidate_roots:
        names = ", ".join(sorted(path.name for path in candidate_roots))
        pytest.fail(
            "Multiple possible output directories found "
            f"({names}). Set VERIFIER_TARGET to the run directory being evaluated."
        )

    return WORKSPACE_DIR


def _artifact_path(name):
    path = _target_root() / name
    assert path.is_file(), f"{name} not found in {_target_root()}"
    return path


def _artifact_text(name):
    return _artifact_path(name).read_text(encoding="utf-8")


def _all_artifact_text():
    parts = []
    for name in DELIVERABLES:
        try:
            parts.append(_artifact_text(name))
        except AssertionError:
            continue
    return "\n".join(parts)


def _plain(text):
    return re.sub(r"\s+", " ", text.lower().replace("\u00a0", " ")).strip()


def _amount_present(text, amount):
    variants = {amount, amount.replace(",", "")}
    if amount.endswith(".00"):
        variants.add(amount[:-3])
        variants.add(amount.replace(",", "")[:-3])
    escaped = "|".join(re.escape(value) for value in sorted(variants, key=len, reverse=True))
    return re.search(rf"\$?\s*(?:{escaped})(?![\d.])", text) is not None


def _near(text, left, right, max_chars=160):
    pattern = rf"{left}.{{0,{max_chars}}}{right}|{right}.{{0,{max_chars}}}{left}"
    return re.search(pattern, _plain(text), flags=re.IGNORECASE | re.DOTALL) is not None


def _read_json(path):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None


def _walk_objects(obj):
    if isinstance(obj, dict):
        yield obj
        for value in obj.values():
            yield from _walk_objects(value)
    elif isinstance(obj, list):
        for item in obj:
            yield from _walk_objects(item)


def _snapshot_json_paths(service=None):
    """Find snapshot JSON files from either snapshots.json or service snapshot folders."""
    paths = []
    seen = set()

    explicit = _find_snapshot()
    if explicit is not None:
        resolved = explicit.resolve()
        seen.add(resolved)
        paths.append(resolved)

    search_roots = []
    for root in (TASK_DIR, Path.cwd(), _target_root()):
        try:
            resolved = root.resolve()
        except OSError:
            continue
        if resolved not in search_roots:
            search_roots.append(resolved)

    pattern = "*.json" if service is None else f"*{service}*.json"
    for root in search_roots:
        if not root.exists():
            continue
        for path in root.rglob(pattern):
            lower = str(path).lower()
            if "snapshot" not in lower:
                continue
            resolved = path.resolve()
            if resolved in seen:
                continue
            seen.add(resolved)
            paths.append(resolved)

    return paths


def _iter_snapshot_records(service=None):
    for path in _snapshot_json_paths(service):
        data = _read_json(path)
        if data is None:
            continue
        yield from _walk_objects(data)


def _iter_fintrack_records():
    for obj in _iter_snapshot_records("fintrack"):
        if isinstance(obj, dict) and "merchant" in obj and "amount" in obj:
            yield obj


def _has_fintrack_record(merchant_pattern, amount):
    for record in _iter_fintrack_records():
        merchant = str(record.get("merchant", ""))
        if re.search(merchant_pattern, merchant, flags=re.IGNORECASE) is None:
            continue
        try:
            value = abs(float(record.get("amount")))
        except (TypeError, ValueError):
            continue
        if round(value, 2) == amount:
            return True
    return False


def _iter_email_records():
    for obj in _iter_snapshot_records("email"):
        if not isinstance(obj, dict):
            continue
        if ("recipients" in obj or "to" in obj) and ("subject" in obj or "folder" in obj or "content" in obj):
            yield obj


def _iter_message_records():
    for obj in _iter_snapshot_records("messaging"):
        if isinstance(obj, dict) and "content" in obj and ("sender_id" in obj or "recipient_id" in obj or "user_id" in obj):
            yield obj


def _sent_to_chloe_via_snapshot():
    for email in _iter_email_records():
        blob = json.dumps(email, sort_keys=True).lower()
        recipients = json.dumps(email.get("recipients", email.get("to", ""))).lower()
        folder = str(email.get("folder", email.get("mailbox", email.get("mailbox_id", "")))).lower()
        if "chloe" not in recipients and "chloe.m.garden@gmail.com" not in blob:
            continue
        if folder and "sent" not in folder:
            continue
        if "fundraising_plan.md" in blob or "fundraising plan" in blob or "grand opening" in blob:
            return True

    for message in _iter_message_records():
        blob = json.dumps(message, sort_keys=True).lower()
        content = str(message.get("content", "")).lower()
        addressed_to_chloe = "p_chloe" in blob or "chloe" in content
        includes_plan = "fundraising plan" in content or "grand opening" in content or "garden fiesta" in content
        from_jennifer_or_agent = "p_jennifer" in blob or "jen" in content or "jennifer" in content
        if addressed_to_chloe and includes_plan and from_jennifer_or_agent:
            return True

    return False


def _contains_any(text, terms):
    lower = _plain(text)
    return any(term in lower for term in terms)


def _contains_all(text, terms):
    lower = _plain(text)
    return all(term in lower for term in terms)


def _stale_budget_claim_present(text):
    lower = _plain(text)
    stale_amounts = ("105.90", "288.40", "532.35", "175.40", "419.35", "1,911", "1911", "2,061", "2061")
    return any(amount in lower for amount in stale_amounts)


def test_required_markdown_deliverables_exist():
    """The run must create the three requested markdown files."""
    for name in DELIVERABLES:
        assert _artifact_path(name).is_file(), f"{name} is missing"


def test_snapshot_contains_required_fintrack_records():
    """The snapshot should contain the finance records needed for the budget calculation."""
    assert _snapshot_json_paths(), "No snapshot JSON files found"
    assert _has_fintrack_record(r"north haven", 78.40), "FinTrack snapshot missing North Haven $78.40"
    assert _has_fintrack_record(r"home depot", 163.20), "FinTrack snapshot missing Home Depot $163.20"
    assert _has_fintrack_record(r"baker creek", 34.85), "FinTrack snapshot missing Baker Creek $34.85"


def test_budget_uses_supported_first_plot_purchase_basis():
    """budget_calculations.md must use the supported no-sales-tax purchase basis."""
    text = _artifact_text("budget_calculations.md")
    lower = _plain(text)

    for merchant in ("north haven", "home depot", "baker creek"):
        assert merchant in lower, f"budget_calculations.md must identify {merchant}"

    for amount in ("78.40", "163.20", "34.85", "276.45"):
        assert _amount_present(text, amount), f"budget_calculations.md missing ${amount}"

    assert _near(text, r"north haven", r"(tax|subtotal|pre-tax|pre tax)", max_chars=220), (
        "North Haven amount should be tied to the tax-split receipt/subtotal rule"
    )
    assert _near(text, r"baker creek", r"(shipping|no sales tax|no tax|full total|total)", max_chars=260), (
        "Baker Creek should retain shipping because it is not a sales-tax line"
    )
    assert _near(text, r"home depot", r"(fintrack|bank|finance|card|transaction|statement|account|record|no price|no pricing)", max_chars=260), (
        "Home Depot should be resolved from a finance/bank record when the delivery email has no price"
    )


def test_budget_remaining_grant_math_is_correct_without_over_prescribing_notation():
    """budget_calculations.md must compute the 7 remaining plots and final grant remainder."""
    text = _artifact_text("budget_calculations.md")
    lower = _plain(text)

    for amount in ("2,500.00", "1,935.15", "564.85"):
        assert _amount_present(text, amount), f"budget_calculations.md missing ${amount}"

    assert re.search(r"\b8\b.{0,80}(total )?plots?", lower) or re.search(r"(total )?plots?.{0,80}\b8\b", lower), (
        "Must state the revised 8 total plot plan"
    )
    assert re.search(r"\b1\b.{0,80}(built|completed|already|pre-grant|pre grant)", lower) or re.search(
        r"(built|completed|already|pre-grant|pre grant).{0,80}\b1\b", lower
    ), "Must account for the 1 already-built plot"
    assert re.search(r"\b7\b.{0,80}(remaining|more|additional|finish|plots?)", lower) or re.search(
        r"(remaining|more|additional|finish|plots?).{0,80}\b7\b", lower
    ), "Must account for 7 remaining plots"
    assert _contains_any(text, ("remaining", "left", "available", "balance")), (
        "Must frame $564.85 as the remaining/available grant budget"
    )
    assert not _stale_budget_claim_present(text), (
        "budget_calculations.md contains stale or unsupported budget amounts from an earlier calculation"
    )
    assert not re.search(r"(home depot).{0,120}(unknown|tbd|retrieve|action needed|could not be verified)", lower), (
        "Home Depot amount must not be left unresolved"
    )


def test_inventory_review_is_evidence_based_not_exact_census():
    """inventory_review.md should be a qualitative evidence review with confidence language."""
    text = _artifact_text("inventory_review.md")
    lower = _plain(text)

    assert "inventory" in lower or "review" in lower, "inventory_review.md should identify itself as a review"
    assert "harvest" in lower, "inventory_review.md must discuss harvestability"
    assert "confidence" in lower or _contains_any(text, ("high", "medium", "low", "uncertain")), (
        "inventory_review.md must mark confidence or uncertainty"
    )
    assert _contains_any(text, ("visible", "appears", "likely", "possible", "could", "uncertain", "not definitive")), (
        "inventory_review.md should use cautious visual-evidence language"
    )
    assert re.search(r"dcim|\.jpg|\.png|\.mp4|photo|video|media", lower), (
        "inventory_review.md should reference the uploaded media evidence at least generally"
    )


def test_inventory_review_grounds_seed_and_start_backed_crops():
    """inventory_review.md must tie the media review to the bought seeds and starts."""
    text = _artifact_text("inventory_review.md")
    lower = _plain(text)

    assert "baker creek" in lower, "Must ground seeds in the Baker Creek order evidence"
    assert "north haven" in lower, "Must ground starts in the North Haven order evidence"
    assert "seed" in lower, "Must discuss seed-backed crops"
    assert "start" in lower, "Must discuss start-backed crops"

    for crop in ("tomato", "pepper", "basil", "beet", "bean", "eggplant"):
        assert crop in lower, f"inventory_review.md should review source-backed {crop} evidence"


def test_inventory_review_separates_purchase_backed_from_other_visual_evidence():
    """The review should distinguish purchase-backed crops from other visual observations."""
    text = _artifact_text("inventory_review.md")
    lower = _plain(text)

    assert _contains_any(
        text,
        (
            "no matching purchase",
            "not in purchase",
            "no purchase record",
            "not tied",
            "not clearly tied",
            "observed-only",
            "observed only",
            "visible in media",
            "other observed",
            "other visually observed",
        ),
    ), (
        "inventory_review.md must separate seed/start-backed crops from other visual evidence "
        "that is not clearly tied to purchase records"
    )

    assert not re.search(
        r"(marigold|ornamental).{0,80}(harvestable|edible|produce)|"
        r"(harvestable|edible|produce).{0,80}(marigold|ornamental)",
        lower,
    ), "Ornamental flowers must not be presented as harvestable produce"


def test_fundraising_plan_uses_correct_budget_context():
    """fundraising_plan.md must use the corrected remaining grant budget."""
    text = _artifact_text("fundraising_plan.md")
    lower = _plain(text)

    assert _amount_present(text, "564.85"), "fundraising_plan.md missing the $564.85 remaining grant budget"
    assert _amount_present(text, "1,935.15"), "fundraising_plan.md missing the $1,935.15 remaining plot cost"
    assert "grant" in lower and "budget" in lower, "fundraising_plan.md must include grant/budget context"
    assert not _stale_budget_claim_present(text), (
        "fundraising_plan.md contains stale or unsupported budget amounts from an earlier calculation"
    )
    assert not re.search(r"(budget gap|budget shortfall|grant shortfall|falls?\s+short|short\s+of\s+covering)", lower), (
        "fundraising_plan.md must not claim a grant budget gap"
    )


def test_fundraising_plan_is_family_friendly_and_constrained_by_evidence():
    """Plan should fit current garden evidence without overpromising unrestricted harvest."""
    text = _artifact_text("fundraising_plan.md")
    lower = _plain(text)

    assert _contains_any(text, ("kids", "children", "families", "family", "visitors", "neighbors")), (
        "Plan must include a family/kids/visitor activity"
    )
    assert _contains_any(text, ("harvest", "pick", "taste", "sample", "take-home", "take home", "produce")), (
        "Plan must use current garden evidence in the activity design"
    )
    assert _contains_any(
        text,
        (
            "limited",
            "small",
            "supervised",
            "cap",
            "capped",
            "one pick",
            "one-pick",
            "while-supplies",
            "while supplies",
            "sample",
            "demonstration",
            "only what is ripe",
        ),
    ), "Plan should constrain produce picking/tasting to the available evidence"

    if "unrestricted" in lower or "pick-your-own" in lower or "pick your own" in lower:
        assert _contains_any(text, ("avoid", "not feasible", "not realistic", "limited", "too early", "do not")), (
            "Plan must not recommend unrestricted pick-your-own from limited evidence"
        )

    assert _contains_any(text, ("late july", "august", "later", "wait", "ripen", "more produce", "larger event")), (
        "Plan should acknowledge that later timing can improve produce availability"
    )


def test_fundraising_plan_was_sent_to_chloe():
    """The fundraising plan must be sent to Chloe by email or message."""
    assert _snapshot_json_paths(), "No snapshot JSON files found"
    assert _sent_to_chloe_via_snapshot(), (
        "No snapshot evidence that the fundraising plan was sent to Chloe by email or message"
    )


if __name__ == "__main__":
    sys.exit(pytest.main([str(Path(__file__).resolve()), "-rA", "--tb=short"]))

